// Replace only the upstream topbar display image; retain Swagger UI behavior.
function applyUniHubBranding() {
  const logo = document.querySelector('.swagger-ui .topbar-wrapper img[alt="Swagger UI"]');
  if (!logo) return false;
  logo.src = "/assets/unihub/unihub-logo-v1.png";
  logo.alt = "UniHub";
  logo.width = 185;
  const link = logo.closest("a");
  if (link) { link.href = "/"; link.setAttribute("aria-label", "UniHub"); }
  return true;
}
const brandingObserver = new MutationObserver(function() {
  if (applyUniHubBranding()) brandingObserver.disconnect();
});
brandingObserver.observe(document.getElementById("swagger-ui"), {childList: true, subtree: true});
// Begin Swagger UI call region
